      ["This metalloid element is widely utilized in semiconductor electronics today.", "यह उपधातु तत्व आज अर्धचालक (semiconductor) इलेक्ट्रॉनिक्स में व्यापक रूप से उपयोग किया जाता है।"],
      "Mendeleev's predicted Eka-Silicon turned out to be Germanium (Ge), discovered in 1886, confirming his predictions regarding valence, density, and melting traits.",
      "मेंडलीफ द्वारा अनुमानित एका-सिलिकॉन बाद में जर्मेनियम (Ge) निकला, जिसकी खोज 1886 में हुई थी, जिसने संयोजकता, घनत्व और गलनांक के संबंध में उनके अनुमानों की पुष्टि की।",
      "easy", 1435
